from pysat.solvers import Solver
from pysat.card import CardEnc, EncType
from itertools import combinations

def edge_var(u, v, n):
    assert u < v
    idx = u * (2*n - u - 1) // 2
    idx += v - u - 1
    return idx + 1

def solve_graph(n, degree, forbid_3=True, forbid_4=True, forbid_5=True, timeout=30):
    total_edges = n * (n - 1) // 2

    adj = [[] for _ in range(n)]
    for u in range(n):
        for v in range(u+1, n):
            var = edge_var(u, v, n)
            adj[u].append(var)
            adj[v].append(var)

    clauses = []
    max_var = total_edges

    # Degree constraints
    if isinstance(degree, int):
        for v in range(n):
            cnf = CardEnc.equals(adj[v], bound=degree, encoding=EncType.totalizer)
            for cl in cnf.clauses:
                clauses.append(cl)
            max_var = max(max_var, cnf.nv)
    else:
        min_deg, max_deg = degree
        for v in range(n):
            cnf_atmost = CardEnc.atmost(adj[v], max_deg, encoding=EncType.totalizer)
            for cl in cnf_atmost.clauses:
                clauses.append(cl)
            max_var = max(max_var, cnf_atmost.nv)

            cnf_atleast = CardEnc.atleast(adj[v], min_deg, encoding=EncType.totalizer)
            for cl in cnf_atleast.clauses:
                clauses.append(cl)
            max_var = max(max_var, cnf_atleast.nv)

    # No triangles
    if forbid_3:
        for a, b, c in combinations(range(n), 3):
            clauses.append([-edge_var(a,b,n), -edge_var(a,c,n), -edge_var(b,c,n)])

    # No 4-cycles
    if forbid_4:
        for a, b, c, d in combinations(range(n), 4):
            clauses.append([-edge_var(a,b,n), -edge_var(b,c,n), -edge_var(c,d,n), -edge_var(a,d,n)])
            clauses.append([-edge_var(a,b,n), -edge_var(b,d,n), -edge_var(c,d,n), -edge_var(a,c,n)])
            clauses.append([-edge_var(a,c,n), -edge_var(b,c,n), -edge_var(b,d,n), -edge_var(a,d,n)])

    # No 5-cycles
    if forbid_5:
        from itertools import permutations
        for verts in combinations(range(n), 5):
            a, b, c, d, e = verts
            for perm in permutations([b,c,d,e]):
                v2, v3, v4, v5 = perm
                if v2 < v5:
                    edges = [(a, v2), (v2, v3), (v3, v4), (v4, v5), (a, v5)]
                    clause = [-edge_var(min(u,v), max(u,v), n) for u, v in edges]
                    clauses.append(clause)

    print(f"n={n}, degree={degree}, clauses={len(clauses)}, max_var={max_var}")

    solver = Solver(name='g3')
    for cl in clauses:
        solver.add_clause(cl)

    sat = solver.solve()
    print(f"SAT: {sat}")

    if sat:
        model = solver.get_model()
        edges = []
        for u in range(n):
            for v in range(u+1, n):
                var = edge_var(u, v, n)
                if var in model:
                    edges.append((u, v))
        print(f"Edges: {edges}")

        deg = [0] * n
        for u, v in edges:
            deg[u] += 1
            deg[v] += 1
        print(f"Degrees: {deg}")

        g = compute_girth(n, edges)
        print(f"Girth: {g}")

